type WorldState = {
  entities: Record<string, string>;
};

const initialState: WorldState = {
  entities: {
    Vok: "pex",
  },
};

const cloneState = (state: WorldState): WorldState => ({
  entities: { ...state.entities },
});

export const protocol: WorldProtocol<WorldState> = {
  reset(): WorldState {
    return cloneState(initialState);
  },

  applyOperation(
    state: WorldState,
    operationDisplayName: string
  ):
    | { success: true; newState: WorldState }
    | { success: false; error: string } {
    const currentState = state.entities.Vok;

    if (operationDisplayName === "advanceVok") {
      if (currentState !== "pex") {
        return {
          success: false,
          error: "advanceVok requires Vok to be in pex",
        };
      }

      const newState = cloneState(state);
      newState.entities.Vok = "dor";
      return { success: true, newState };
    }

    if (operationDisplayName === "recoverVok") {
      if (currentState !== "dor") {
        return {
          success: false,
          error: "recoverVok requires Vok to be in dor",
        };
      }

      const newState = cloneState(state);
      newState.entities.Vok = "pex";
      return { success: true, newState };
    }

    return {
      success: false,
      error: `Unknown operation: ${operationDisplayName}`,
    };
  },

  getEntityState(state: WorldState, entityDisplayName: string): string {
    return state.entities[entityDisplayName] ?? "unknown";
  },

  toAbstractSnapshot(state: WorldState): Record<string, string> {
    return { ...state.entities };
  },
};
